mapper.select:
select f.id,f.fd_key,f.fd_car_no, IFNULL(f.fd_car_belong,t.fd_car_belong) fd_car_belong, IFNULL(f.fd_driver_name,T.fd_driver_name) fd_driver_name, IFNULL(f.fd_protect_grade,T.fd_protect_grade) fd_protect_grade, IFNULL(f.fd_detailed_img,T.fd_detailed_img) fd_detailed_img, IFNULL(f.fd_vin,T.fd_vin) fd_vin, IFNULL(f.fd_engine,T.fd_engine) fd_engine, IFNULL(f.fd_car_img,T.fd_car_img) fd_car_img, IFNULL(f.fd_car_date,T.fd_car_date) fd_car_date, fd_state_code,tp.flow_id, f.fd_dock_no,f.fd_dock_name,per.fd_per_name enter_drvier_name, per.fd_per_phone enter_drvier_phone, f.fd_supplier_code,f.fd_supplier_name from safety_enter_filing f left join safety_enter_filing_approve a on f.id=a.fd_filing_id left join safety_enter_protect t on f.fd_car_no=t.fd_car_no left join safety_enter_process tp on f.id = tp.form_instance_id left join safety_enter_filing_per per on per.filing_id = f.id and per.fd_per_type_code = '10' where f.id in
#{item}
and a.fd_filing_end > now() and a.fd_filing_begin <= now() and f.fd_state_code in('30','31')

select a.fd_filing_id,a.fd_filing_factory_code,a.fd_filing_factory, a.approve_code,a.approve_name,m.phone_no approve_phone, date_format(a.fd_filing_begin,'%Y-%m-%d %H:%i:%s') fd_filing_begin, date_format(a.fd_filing_end,'%Y-%m-%d %H:%i:%s') fd_filing_end from safety_enter_filing f left join safety_enter_filing_approve a on f.id=a.fd_filing_id left join safety_employee_message m on m.emp_no = a.approve_code and m.status='normal' where f.fd_key=#{fdKey}
and a.fd_filing_end > now() and a.fd_filing_begin <= now()
and f.fd_state_code in ('30','31')
